public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> permutations = new ArrayList<>();

    permuteHelper(nums, 0, new ArrayList<>(), permutations);

    return permutations;
}

private void permuteHelper(int[] nums, int index, List<Integer> currentPermutation, List<List<Integer>> permutations) {
    if (index == nums.length) {
        permutations.add(new ArrayList<>(currentPermutation));
        return;
    }

    for (int i = 0; i < nums.length; i++) {
        if (!currentPermutation.contains(nums[i])) {
            currentPermutation.add(nums[i]);
            permuteHelper(nums, index + 1, currentPermutation, permutations);
            currentPermutation.remove(currentPermutation.size() - 1);
        }
    }
}

public List<List<Integer>> permute(int[] nums) {
    // Edge case: If the input array has only one element, return the array with that element
    if (nums.length == 1) {
        return Arrays.asList(nums);
    }

    // Initialize the result list
    List<List<Integer>> result = new ArrayList<>();

    // Iterate over all possible permutations of the input array
    for (int i = 0; i < nums.length; i++) {
        // Generate a list of all permutations of the remaining elements
        List<List<Integer>> permutations = permute(Arrays.copyOfRange(nums, 1, nums.length));

        // Iterate over all permutations and append the current element to each one
        for (List<Integer> permutation : permutations) {
            permutation.add(0, nums[i]);
            result.add(permutation);
        }
    }

    // Return the result list
    return result;
}

