public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {

        // Validate input
        if (n <= 0 || start == null || end == null || paths == null) {
            throw new IllegalArgumentException("Invalid input");
        }
        if (start.length != 2 || end.length != 2 || paths.length != n) {
            throw new IllegalArgumentException("Invalid input dimensions");
        }

        // Initialize visited array
        boolean[] visited = new boolean[n];

        // Add starting n-tersection to visited array
        visited[start[0] * n + start[1]] = true;

        // Initialize queue for BFS
        ArrayDeque<int[]> queue = new ArrayDeque<>();
        queue.add(start);

        // Do BFS
        while (!queue.isEmpty()) {
            int[] current = queue.removeFirst();

            // If current cell is the ending n-tersection, return "can be travelled"
            if (current[0] == end[0] && current[1] == end[1]) {
                return "can be travelled";
            }

            // Get neighboring cells
            int[][] neighbors = new int[][] {
                { current[0] - 1, current[1] },
                { current[0] + 1, current[1] },
                { current[0], current[1] - 1 },
                { current[0], current[1] + 1 }
            };

            // Enqueue neighboring cells that are not visited and have a valid path in paths
            for (int[] neighbor : neighbors) {
                if (neighbor[0] >= 0 && neighbor[1] >= 0 && neighbor[0] < n && neighbor[1] < n && !visited[neighbor[0] * n + neighbor[1]]) {
                    if (isValidPath(paths, current, neighbor)) {
                        visited[neighbor[0] * n + neighbor[1]] = true;
                        queue.add(neighbor);
                    }
                }
            }
        }

        // If the ending n-tersection is not reachable, return "cannot be travelled"
        return "cannot be travelled";
    }

