         return "can be travelled";
      }

      // get neighbors of current n-intersection
      int[] neighbors = getNeighbors(curr, paths);

      // mark neighbors as visited
      for (int neighbor : neighbors) {
         visited[neighbor] = true;
      }

      // enqueue neighbors
      queue.addAll(neighbors);
   }

   // if no path found, return "cannot be travelled"
   return "cannot be travelled";
}

private static int[] getNeighbors(int n, int[][] paths) {
   // check if given n-intersection is valid
   if (n < 0 || n >= paths.length) {
      throw new IllegalArgumentException("Invalid n-intersection");
   }

   // get neighbors of given n-intersection
   int[] neighbors = new int[paths[n].length];
   for (int i = 0; i < neighbors.length; i++) {
      neighbors[i] = paths[n][i];
   }

   return neighbors;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Check if the start and end coordinates are valid
    if (start.length != 2 || end.length != 2) {
        throw new IllegalArgumentException("Invalid coordinates");
    }

    // Check if the paths array is valid
    if (paths.length != n || paths[0].length != n) {
        throw new IllegalArgumentException("Invalid path array");
    }

    // Initialize a boolean array to keep track of visited n-tersections
    boolean[] visited = new boolean[n];

    // Initialize a stack to keep track of the n-tersections to visit
    Stack<Integer> stack = new Stack<>();

    // Add the starting n-tersection to the stack
    stack.push(start[0] * n + start[1]);

    // Loop until the stack is empty
    while (!stack.isEmpty()) {
        // Get the current n-tersection
        int curr = stack.pop();

        // Check if the current n-tersection is the ending n-tersection
        if (curr == end[0] * n + end[1]) {
            return "can be travelled";
        }

        // Mark the current n-tersection as visited
        visited[curr] = true;

        // Loop through the paths
        for (int i = 0; i < paths[curr].length; i++) {
            // If the current path is not visited and it leads to an unvisited n-tersection, add it to the stack
            int path = curr + paths[curr][i];
            if (!visited[path]) {
                stack.push(path);
            }
        }
    }

    // If the stack is empty, return "cannot be travelled"
    return "cannot be travelled";
}

