private static boolean isValidDate(String date) {
    // Check if the date string has three parts separated by spaces
    String[] parts = date.split("\\s+");
    if (parts.length != 3) {
        return false;
    }

    // Check if the date string contains only digits
    for (String part : parts) {
        if (!part.matches("\\d+")) {
            return false;
        }
    }

    // Check if the month and day are in the valid range
    int month = Integer.parseInt(parts[0]);
    int day = Integer.parseInt(parts[1]);
    if (month < 1 || month > 12 || day < 1 || day > 31) {
        return false;
    }

    // Check if the year is valid
    int year = Integer.parseInt(parts[2]);
    if (year < 0 || year > 9999) {
        return false;
    }

    return true;
}

