  }
  // search the left and right subarrays
  int left = searchLeft(nums, target, 0, pivot - 1);
  int right = searchRight(nums, target, pivot, nums.length - 1);
  // return the first index found
  if (left != -1) {
    return left;
  } else {
    return right;
  }
}

