public double trimMean(int[] arr) {
    // Sort the array in ascending order
    Arrays.sort(arr);

    // Find the smallest 5% of elements and remove them
    int startIndex = (int) Math.ceil(0.05 * arr.length);
    int endIndex = (int) Math.floor(0.95 * arr.length);
    int[] trimmedArr = Arrays.copyOfRange(arr, startIndex, endIndex);

    // Calculate the mean of the remaining elements
    double mean = mean(trimmedArr);

    return mean;
}

public double mean(int[] arr) {
    // Calculate the sum of the elements in the array
    int sum = 0;
    for (int elem : arr) {
        sum += elem;
    }

    // Calculate the mean
    double mean = (double) sum / arr.length;

    return mean;
}

public double trimMean(int[] arr) {
    // Sort the array in non-decreasing order
    Arrays.sort(arr);

    // Calculate the number of elements to be removed from the start and end
    int startIdx = (int) (arr.length * 0.05);
    int endIdx = arr.length - startIdx - 1;

    // Calculate the sum of the middle elements
    int sum = 0;
    for (int i = startIdx; i < endIdx; i++) {
        sum += arr[i];
    }

    // Calculate the mean of the middle elements
    double mean = (double) sum / (endIdx - startIdx);

    // Return the mean with an error within 10^-5
    return mean;
}

public double trimMean(int[] arr) {
    // Check for invalid input
    if (arr == null || arr.length == 0) {
        throw new IllegalArgumentException("Invalid input: empty array");
    }

    // Initialize variables
    int[] sortedArr = Arrays.copyOf(arr, arr.length);
    Arrays.sort(sortedArr);
    int total = 0;
    int count = 0;

    // Calculate the mean
    for (int i = 0; i < arr.length; i++) {
        total += arr[i];
        count++;
    }
    double mean = (double) total / count;

    // Remove the smallest and largest 5% of elements
    int sliceSize = (int) (arr.length * 0.05);
    int sliceStart = (arr.length - sliceSize) / 2;
    for (int i = sliceStart; i < sliceStart + sliceSize; i++) {
        arr[i] = 0;
    }

    // Calculate the mean of the remaining elements
    total = 0;
    count = 0;
    for (int i = 0; i < arr.length; i++) {
        if (arr[i] != 0) {
            total += arr[i];
            count++;
        }
    }
    double trimMean = (double) total / count;

    // Return the trimmed mean with an error of 10^-5
    double error = Math.abs(mean - trimMean);
    if (error < 0.00001) {
        return trimMean;
    } else {
        throw new IllegalStateException("Error calculating trimmed mean: " + error);
    }
}

public double trimMean(int[] arr) {
    // Sort the array in ascending order
    Arrays.sort(arr);

    // Calculate the total number of elements in the array
    int total = arr.length;

    // Calculate the smallest 5% of elements
    int smallest5 = (int) (total * 0.05);

    // Calculate the largest 5% of elements
    int largest5 = (int) (total * 0.05);

    // Calculate the sum of the remaining elements
    int sum = 0;
    for (int i = smallest5; i < total - largest5; i++) {
        sum += arr[i];
    }

    // Calculate the mean
    double mean = (double) sum / (total - 2 * smallest5 - 2 * largest5);

    // Round the mean to 5 decimal places
    mean = round(mean, 5);

    return mean;
}

public double round(double value, int places) {
    if (places < 0) throw new IllegalArgumentException();

    long factor = (long) Math.pow(10, places);
    value = value * factor;
    long temp = Math.round(value);
    return (double) temp / factor;
}

public double trimMean(int[] arr) {
  // First, sort the array in ascending order
  Arrays.sort(arr);

  // Calculate the mean of the remaining elements after removing the smallest 5% and largest 5% of the elements
  int smallestElements = (int) Math.floor(arr.length * 0.05);
  int largestElements = (int) Math.ceil(arr.length * 0.05);
  double sum = 0;
  for (int i = smallestElements; i < arr.length - largestElements; i++) {
    sum += arr[i];
  }
  double mean = sum / (arr.length - 2 * smallestElements);

  // Round the mean to 5 decimal places
  return Math.round(mean * Math.pow(10, 5)) / Math.pow(10, 5);
}

public boolean canArrange(int[] arr, int k) {
        Map<Integer, Integer> pairSums = new HashMap<>();
        int[] sumPairs = new int[arr.length / 2];

        for (int i = 0; i < arr.length; i++) {
            for (int j = i + 1; j < arr.length; j++) {
                int pairSum = arr[i] + arr[j];
                if (pairSum % k == 0) {
                    if (pairSums.containsKey(pairSum)) {
                        pairSums.put(pairSum, pairSums.get(pairSum) + 1);
                    } else {
                        pairSums.put(pairSum, 1);
                    }
                }
            }
        }

        for (Map.Entry<Integer, Integer> entry : pairSums.entrySet()) {
            sumPairs[entry.getValue()] = entry.getKey();
        }

        for (int i = 0; i < sumPairs.length; i++) {
            if (sumPairs[i] == 0) {
                return false;
            }
        }

        return true;
    }

