        return false;
    }

    // Create a hash set to keep track of the pairs
    Set<Integer> pairs = new HashSet<>();

    // Loop through the array and add each pair to the hash set
    for (int i = 0; i < arr.length; i++) {
        for (int j = i + 1; j < arr.length; j++) {
            if (arr[i] + arr[j] % k == 0) {
                pairs.add(arr[i] + arr[j]);
            }
        }
    }

    // Return true if the hash set size is equal to the number of pairs
    // and the hash set size is equal to the number of pairs
    return pairs.size() == arr.length / 2 && pairs.size() == pairs.size();
}

public boolean canArrange(int[] arr, int k) {
    // Check if the input array is empty or has odd number of elements
    if (arr.length <= 0 || (arr.length % 2) != 0) {
        return false;
    }

    // Initialize a list to store the pairs
    List<Integer> pairs = new ArrayList<>();

    // Iterate through the array and add pairs to the list
    for (int i = 0; i < arr.length; i++) {
        int num1 = arr[i];
        int num2 = arr[i + 1];
        pairs.add(num1 + num2);
        i++;
    }

    // Check if the sum of each pair is divisible by k
    for (Integer pair : pairs) {
        if (pair % k != 0) {
            return false;
        }
    }

    return true;
}

