public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Check if the input is valid
    if (n < 0 || edges == null || hasApple == null || edges.length != hasApple.length) {
        throw new IllegalArgumentException("Invalid input");
    }

    // Initialize the distance array with maximum value
    int[] distance = new int[n];
    for (int i = 0; i < n; i++) {
        distance[i] = Integer.MAX_VALUE;
    }

    // Initialize the queue with the starting node
    Queue<Integer> queue = new LinkedList<>();
    queue.add(0);

    // Initialize the time variable
    int time = 0;

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Get the node at the front of the queue
        int node = queue.poll();

        // Check if we have found all the apples
        if (hasApple[node]) {
            return time;
        }

        // Update the distance array
        for (int[] edge : edges) {
            if (node == edge[0]) {
                int neighbor = edge[1];
                if (distance[neighbor] > time + 1) {
                    distance[neighbor] = time + 1;
                    queue.add(neighbor);
                }
            }
        }

        // Increment the time
        time++;
    }

    // Return the maximum time
    return time;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
  if (hasApple[0]) {
    return 0;
  }
  int[] dist = new int[n];
  int[] visited = new int[n];
  Arrays.fill(dist, Integer.MAX_VALUE);
  dist[0] = 0;
  Queue<Integer> queue = new LinkedList<>();
  queue.offer(0);
  while (!queue.isEmpty()) {
    int node = queue.poll();
    if (visited[node] == 1) {
      continue;
    }
    visited[node] = 1;
    for (int[] edge : edges) {
      if (edge[0] == node && !hasApple[edge[1]]) {
        dist[edge[1]] = Math.min(dist[edge[1]], dist[node] + 1);
        queue.offer(edge[1]);
      }
    }
  }
  return dist[n - 1] == Integer.MAX_VALUE ? -1 : dist[n - 1];
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // List of nodes that have been visited
    List<Integer> visited = new ArrayList<>();
    // Distance from the starting node to the current node
    Map<Integer, Integer> distance = new HashMap<>();
    // Time needed to collect apples at each node
    Map<Integer, Integer> appleTime = new HashMap<>();

    // Initialize the distance and appleTime maps
    for (int i = 0; i < n; i++) {
        distance.put(i, Integer.MAX_VALUE);
        appleTime.put(i, 0);
    }

    // Start BFS from node 0
    Queue<Integer> queue = new LinkedList<>();
    queue.offer(0);
    distance.put(0, 0);

    // Explore all reachable nodes
    while (!queue.isEmpty()) {
        int node = queue.poll();
        // If the current node has not been visited before, visit it and mark it as visited
        if (!visited.contains(node)) {
            visited.add(node);
            // Update the distance and appleTime maps for the current node
            distance.put(node, distance.get(node) + 1);
            if (hasApple[node]) {
                appleTime.put(node, distance.get(node));
            }
        }
        // Explore the neighbors of the current node
        for (int neighbor : neighbors(node, edges)) {
            if (!visited.contains(neighbor)) {
                queue.offer(neighbor);
            }
        }
    }

    // Calculate the minimum time required to collect all apples
    int time = 0;
    for (int apple : appleTime.keySet()) {
        time = Math.max(time, appleTime.get(apple) + distance.get(apple));
    }
    return time;
}

private List<Integer> neighbors(int node, int[][] edges) {
    List<Integer> neighbors = new ArrayList<>();
    for (int[] edge : edges) {
        if (edge[0] == node) {
            neighbors.add(edge[1]);
        }
    }
    return neighbors;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Build a graph representation of the tree
    List<Integer>[] graph = new ArrayList[n];
    for (int i = 0; i < n; i++) {
        graph[i] = new ArrayList<>();
    }
    for (int[] edge : edges) {
        int start = edge[0];
        int end = edge[1];
        graph[start].add(end);
        graph[end].add(start);
    }

    // Build a BFS queue and a boolean array to keep track of visited nodes
    Queue<Integer> queue = new LinkedList<>();
    boolean[] visited = new boolean[n];
    queue.offer(0);
    visited[0] = true;

    // Keep track of the time and the apple collection
    int time = 0;
    int applesCollected = 0;

    while (!queue.isEmpty()) {
        // Get the current node from the queue
        int node = queue.poll();

        // Check if the node has an apple
        if (hasApple[node]) {
            applesCollected++;
        }

        // Visit all the neighbors of the current node
        for (int neighbor : graph[node]) {
            if (!visited[neighbor]) {
                visited[neighbor] = true;
                queue.offer(neighbor);
            }
        }

        // Increment the time
        time++;
    }

    // Return the minimum time required to collect all apples and return to node 0
    return Math.min(time, applesCollected);
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Step 1: Collect the nodes that have apples and add them to a set
    Set<Integer> appleNodes = new HashSet<>();
    for (int i = 0; i < hasApple.length; i++) {
        if (hasApple[i]) {
            appleNodes.add(i);
        }
    }

    // Step 2: Perform a BFS to find the shortest path to all other nodes
    Queue<Integer> queue = new LinkedList<>();
    queue.offer(0);
    int[] prevs = new int[n];
    Arrays.fill(prevs, -1);
    while (!queue.isEmpty()) {
        int node = queue.poll();
        for (int neighbor : edges[node]) {
            if (prevs[neighbor] == -1) {
                prevs[neighbor] = node;
                queue.offer(neighbor);
            }
        }
    }

    // Step 3: Calculate the shortest time from each node to node 0 or the apple nodes
    int[] dists = new int[n];
    for (int i = 0; i < n; i++) {
        dists[i] = Integer.MAX_VALUE;
    }
    for (int node : appleNodes) {
        dists[node] = 0;
    }
    for (int i = 1; i < n; i++) {
        for (int j = 0; j < n; j++) {
            int dist = dists[j] + 1;
            if (prevs[j] != -1) {
                dist = Math.min(dist, dists[prevs[j]] + 1);
            }
            dists[j] = dist;
        }
    }

    // Step 4: Return the shortest time required to collect all apples
    int minTime = Integer.MAX_VALUE;
    for (int i = 0; i < n; i++) {
        if (appleNodes.contains(i)) {
            minTime = Math.min(minTime, dists[i]);
        }
    }
    return minTime;
}

