public String sortString(String s) {
  // Check if the input string is empty
  if (s.isEmpty()) {
    return "";
  }

  // Create a new result string
  String result = "";

  // Create a map to keep track of the characters and their frequencies
  Map<Character, Integer> charFreq = new HashMap<>();
  for (char c : s.toCharArray()) {
    if (charFreq.containsKey(c)) {
      charFreq.put(c, charFreq.get(c) + 1);
    } else {
      charFreq.put(c, 1);
    }
  }

  // Iterate through the characters in the map
  while (!charFreq.isEmpty()) {
    // Get the character with the smallest frequency
    char smallestFreqChar = getSmallestFrequencyChar(charFreq);
    result = result + smallestFreqChar;

    // Get the character that is greater than the last added character and has the smallest frequency
    char nextSmallestFreqChar = getNextSmallestFrequencyChar(charFreq, smallestFreqChar);
    result = result + nextSmallestFreqChar;

    // Decrement the frequency of the chars we just added
    charFreq.put(smallestFreqChar, charFreq.get(smallestFreqChar) - 1);
    charFreq.put(nextSmallestFreqChar, charFreq.get(nextSmallestFreqChar) - 1);
  }

  return result;
}

private char getSmallestFrequencyChar(Map<Character, Integer> charFreq) {
  char smallestFreqChar = '\0';
  int smallestFreq = Integer.MAX_VALUE;
  for (Map.Entry<Character, Integer> entry : charFreq.entrySet()) {
    if (entry.getValue() < smallestFreq) {
      smallestFreq = entry.getValue();
      smallestFreqChar = entry.getKey();
    }
  }
  return smallestFreqChar;
}

private char getNextSmallestFrequencyChar(Map<Character, Integer> charFreq, char lastChar) {
  char nextSmallestFreqChar = '\0';
  int nextSmallestFreq = Integer.MAX_VALUE;
  for (Map.Entry<Character, Integer> entry : charFreq.entrySet()) {
    if (entry.getKey() > lastChar && entry.getValue() < nextSmallestFreq) {
      nextSmallestFreq = entry.getValue();
      nextSmallestFreqChar = entry.getKey();
    }
  }
  return nextSmallestFreqChar;
}

public String sortString(String s) {
    StringBuilder result = new StringBuilder();

    while (s.length() > 0) {
        char smallest = s.charAt(0);
        result.append(smallest);
        s = s.substring(1);

        while (s.length() > 0 && smallest < s.charAt(0)) {
            char nextSmallest = s.charAt(0);
            result.append(nextSmallest);
            s = s.substring(1);
        }

        char largest = s.charAt(s.length() - 1);
        result.append(largest);
        s = s.substring(0, s.length() - 1);

        while (s.length() > 0 && largest > s.charAt(s.length() - 1)) {
            char nextLargest = s.charAt(s.length() - 1);
            result.append(nextLargest);
            s = s.substring(0, s.length() - 1);
        }
    }

    return result.toString();
}

public static String sortString(String s) {
    String result = "";

    // Pick the smallest character from s and append it to the result
    int minIndex = s.indexOf(s.charAt(0));
    result += s.charAt(minIndex);
    s = s.replace(s.charAt(minIndex), "");

    // Pick the smallest character from s which is greater than the last appended character to the result and append it
    int nextMinIndex = s.indexOf(result.charAt(result.length() - 1)) + 1;
    while (nextMinIndex != -1 && s.charAt(nextMinIndex) <= result.charAt(result.length() - 1)) {
      nextMinIndex += s.indexOf(s.charAt(nextMinIndex), nextMinIndex + 1);
    }
    if (nextMinIndex != -1) {
      result += s.charAt(nextMinIndex);
      s = s.replace(s.charAt(nextMinIndex), "");
    }

    // Repeat step 2 until you cannot pick more characters
    while (!s.isEmpty()) {
      // Pick the largest character from s and append it to the result
      int maxIndex = s.indexOf(s.charAt(s.length() - 1));
      result = result.charAt(result.length() - 1) + s.charAt(maxIndex);
      s = s.replace(s.charAt(maxIndex), "");

      // Pick the largest character from s which is smaller than the last appended character to the result and append it
      int nextMaxIndex = s.indexOf(result.charAt(result.length() - 1)) - 1;
      while (nextMaxIndex != -1 && s.charAt(nextMaxIndex) >= result.charAt(result.length() - 1)) {
        nextMaxIndex -= s.indexOf(s.charAt(nextMaxIndex), nextMaxIndex - 1);
      }
      if (nextMaxIndex != -1) {
        result += s.charAt(nextMaxIndex);
        s = s.replace(s.charAt(nextMaxIndex), "");
      }
    }

    return result;
  }

public boolean splitArraySameAverage(int[] nums) {
    // Calculate the sum of all elements in the array
    int sum = 0;
    for (int i = 0; i < nums.length; i++) {
        sum += nums[i];
    }

    // Calculate the average of the array
    int average = sum / nums.length;

    // Initialize two variables to keep track of the sum of the left and right subarrays
    int leftSum = 0;
    int rightSum = 0;

    // Iterate through the array and split it into two subarrays
    for (int i = 0; i < nums.length; i++) {
        if (leftSum <= rightSum) {
            leftSum += nums[i];
        } else {
            rightSum += nums[i];
        }
    }

    // Check if the average of the two subarrays is the same
    return leftSum == average && rightSum == average;
}

