    int sum = 0;
    for (int num : nums) {
      sum += num;
    }

    // Calculate the average of the array
    int average = sum / nums.length;

    // Check if any element in the array is equal to the average
    for (int num : nums) {
      if (num == average) {
        return true;
      }
    }

    // Check if any two elements in the array add up to the average
    for (int i = 0; i < nums.length - 1; i++) {
      for (int j = i + 1; j < nums.length; j++) {
        if (nums[i] + nums[j] == average) {
          return true;
        }
      }
    }

    // If no element or two elements add up to the average, return false
    return false;
  }

