    }
    average /= nums.length;

    // Check if the array has an odd number of elements
    if (nums.length % 2 == 1) {
        // If the array has an odd number of elements, we can't split it into two arrays with the same average
        return false;
    }

    // Check if any of the subarrays are equal to the average
    for (int i = 0; i < nums.length; i++) {
        int sum = 0;
        for (int j = i; j < nums.length; j++) {
