    int currentCost = 0;

    // Loop through the cost array
    for (int i = 0; i < cost.length; i++) {
        // Sum the current cost with the current step cost
        currentCost += cost[i];

        // Update the minimum cost if it is smaller than the current cost
        if (minCost > currentCost) {
            minCost = currentCost;
        }

        // Reset the current cost
        currentCost = 0;
    }

