    dp[0] = cost[0];
    dp[1] = cost[1];
    for (int i = 2; i < cost.length; i++) {
        dp[i] = Math.min(dp[i - 1], dp[i - 2]) + cost[i];
    }
    return Math.min(dp[cost.length - 1], dp[cost.length - 2]);
}

public int minCostClimbingStairs(int[] cost) {
int n = cost.length;
if (n == 2) {
return cost[0] + cost[1];
}
if (n == 3) {
return Math.min(cost[0] + cost[1] + cost[2], cost[1] + cost[2]);
}
int dp1 = cost[0];
int dp2 = cost[1];
for (int i = 2; i < n; i++) {
int costI = cost[i];
dp1 = Math.min(dp1, dp2) + costI + cost[i - 2];
dp2 = Math.min(costI, dp1) + cost[i - 1];
}
return Math.min(dp1, dp2);
}

