        }
    }
    return true;
}

public boolean hasAllCodes(String s, int k) {
	// check if the input string is null or empty
	if (s == null || s.isEmpty()) {
		return false;
	}

	// check if the input length is valid
	if (k < 1 || k > s.length()) {
		return false;
	}

	// create a set to store the substrings
	Set<String> substrings = new HashSet<>();

	// loop through each substring of length k in the input string
	for (int i = 0; i < s.length() - k + 1; i++) {
		substrings.add(s.substring(i, i + k));
	}

	// check if the set contains all possible substrings
	return substrings.size() == (int) Math.pow(2, k);
}

public boolean hasAllCodes(String s, int k) {
    // Check if the input string is null or empty
    if (s == null || s.isEmpty()) {
        return false;
    }

    // Check if the length of the input string is less than the required length for a substring of length k
    if (s.length() < k) {
        return false;
    }

    // Initialize a bitset to keep track of seen substrings
    BitSet seenSubstrings = new BitSet(k);

    // Iterate over the input string
    for (int i = 0; i < s.length() - k + 1; i++) {
        // Extract the substring of length k from the current position in the input string
        String substring = s.substring(i, i + k);

        // Check if the substring is already in the seenSubstrings bitset
        if (seenSubstrings.get(substring)) {
            // If a substring is already in the seenSubstrings bitset, it means that there is a duplicate, return false
            return false;
        } else {
            // If the substring is not in the seenSubstrings bitset, add it and continue the loop
            seenSubstrings.set(substring);
        }
    }

    // Return true if all substrings are unique, false otherwise
    return true;
}

public boolean hasAllCodes(String s, int k) {
    if (k > s.length()) {
