public int minInsertions(String s) {
    int left = 0, right = 0, insertions = 0;

    // Loop through the string and keep track of the number of left and right brackets
    for (char c : s.toCharArray()) {
        if (c == '(') left++;
        else if (c == ')') right++;
    }

    // Add insertions for any unmatched right brackets
    for (int i = 0; i < right; i++) {
        insertions += left > 0 ? 1 : 0;
        left--;
    }

    return insertions;
}

