public int minOperations(int n) {
    int[] arr = new int[n];
    for (int i = 0; i < n; i++) {
        arr[i] = (2 * i) + 1;
    }
    int minOps = 0;
    while (!isEqual(arr)) {
        int[] minOpsArr = new int[n];
        for (int i = 0; i < n; i++) {
            minOpsArr[i] = Integer.MAX_VALUE;
        }
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                int currOps = getOps(arr[i], arr[j]);
                if (currOps < minOpsArr[i]) {
                    minOpsArr[i] = currOps;
                }
            }
        }
        for (int i = 0; i < n; i++) {
            arr[i] -= minOpsArr[i];
        }
        minOps++;
    }
    return minOps;
}

private boolean isEqual(int[] arr) {
    for (int i = 0; i < arr.length - 1; i++) {
        if (arr[i] != arr[i + 1]) {
            return false;
        }
    }
    return true;
}

private int getOps(int a, int b) {
    return Math.abs(a - b);
}

public int minOperations(int n) {
    int minOps = 0;
    int[] arr = new int[n];
    for (int i = 0; i < n; i++) {
        arr[i] = (2 * i) + 1;
    }
    for (int i = 0; i < n; i++) {
        int x = i, y = (i + 1) % n;
        while (arr[x] != arr[y]) {
            arr[x] -= 1;
            arr[y] += 1;
            minOps++;
            x = (x + 1) % n;
            y = (y + 1) % n;
        }
    }
    return minOps;
}

public int minOperations(int n) {
    if (n == 1) return 0;

    // Calculate the sum of the array
    int sum = n * (n + 1) / 2;

    // Calculate the minimum number of operations required to make all elements equal
    int minOps = (sum / n) - 1;

    // Return the minimum number of operations
    return minOps;
}

