public int findMinFibonacciNumbers(int k) {
    // Initialize the Fibonacci sequence with the first two numbers
    int[] fib = {1, 1};

    // Loop until the sum of the next fibonacci number is greater than k
    while (fib[fib.length - 1] + fib[fib.length - 2] <= k) {
        // Add the next fibonacci number to the array
        fib = Arrays.copyOf(fib, fib.length + 1);
        fib[fib.length - 1] = fib[fib.length - 2] + fib[fib.length - 3];
    }

    // Return the length of the fibonacci array
    return fib.length;
}

public int findMinFibonacciNumbers(int k) {
    // Initialize the minimum number of Fibonacci numbers to the given k.
    int minFibonacciNumbers = k;

    // Initialize the sum of the Fibonacci numbers to 0.
    int sum = 0;

    // Initialize the array to store the Fibonacci numbers.
    int[] fibonacciNumbers = new int[k];

    // Iterate over the Fibonacci numbers, starting from the largest.
    for (int i = fibonacciNumbers.length - 1; i >= 0; i--) {
        // If the sum of the current Fibonacci number and the previous Fibonacci number is less than k,
        // set the current Fibonacci number to the previous Fibonacci number and continue.
        if (sum + fibonacciNumbers[i] < k) {
            fibonacciNumbers[i] = fibonacciNumbers[i - 1];
            continue;
        }

        // If the sum of the current Fibonacci number and the previous Fibonacci number is greater than k,
        // set the minimum number of Fibonacci numbers to the current index.
        if (sum + fibonacciNumbers[i] > k) {
            minFibonacciNumbers = i;
            break;
        }

        // If the sum of the current Fibonacci number and the previous Fibonacci number is equal to k,
        // return the minimum number of Fibonacci numbers.
        if (sum + fibonacciNumbers[i] == k) {
            return minFibonacciNumbers;
        }
    }

    // If the minimum number of Fibonacci numbers is less than the given k,
    // return the minimum number of Fibonacci numbers.
    if (minFibonacciNumbers < k) {
        return minFibonacciNumbers;
    }

    // If the minimum number of Fibonacci numbers is greater than the given k,
    // return 0.
    return 0;
}

