        fibonacci[fibonacci.length] = fibonacci[fibonacci.length - 1] + fibonacci[fibonacci.length - 2];
        // Increment the sum of the Fibonacci numbers
        sum += fibonacci[fibonacci.length];
        // Increment the minimum number of Fibonacci numbers required
        minFibonacciCount++;
    }

    // If the sum of the Fibonacci numbers is greater than the given k, return the minimum number of Fibonacci numbers required
    if (sum > k) {
