    if (sum == k) {
        return 2;
    }

    // Loop through the Fibonacci numbers
    while (sum < k) {
        // Check if the sum is equal to k
        if (sum == k) {
            return min + 1;
        }

        // Update the variables
        min++;
        int fib3 = fib1 + fib2;
        fib1 = fib2;
        fib2 = fib3;
        sum = fib1 + fib2;
    }

    // If no Fibonacci numbers satisfy the condition, return -1
    return -1;
}

public int kthFactor(int n, int k) {
   int[] factors = getFactors(n);
   if (k > factors.length) {
       return -1;
   }
   return factors[k - 1];
}

private int[] getFactors(int n) {
   int[] factors = new int[n / 2];
   for (int i = 1; i <= n / 2; i++) {
       if (n % i == 0) {
           factors[factors.length - 1] = i;
       }
   }
   return factors;
}

public int kthFactor(int n, int k) {
    // Check if k is a valid index
    if (k <= 0) {
        throw new IllegalArgumentException("k must be a positive integer");
    }

    // Check if n is a valid input
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer");
    }

    // Initialize a list to store the factors
    List<Integer> factors = new ArrayList<>();

    // Iterate from 1 to n and check if each number is a factor of n
    for (int i = 1; i <= n; i++) {
        if (n % i == 0) {
            factors.add(i);
        }
    }

    // Check if the list has at least k elements
    if (factors.size() < k) {
        return -1;
    }

    // Return the kth element of the list
    return factors.get(k - 1);
}

public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) {
        throw new IllegalArgumentException("n and k must be positive integers");
    }

    int count = 0;
    for (int i = 1; i <= n; i++) {
        if (n % i == 0) {
            count++;
            if (count == k) {
                return i;
            }
        }
    }

    return -1;
}

public int kthFactor(int n, int k) {
    // Check if n and k are valid
    if (n <= 0 || k <= 0) {
        throw new IllegalArgumentException("n and k must be positive integers");
    }

    // Initialize a list to store the factors of n
    List<Integer> factors = new ArrayList<>();

    // Iterate from 1 to n and check if each number is a factor of n
    for (int i = 1; i <= n; i++) {
        if (n % i == 0) {
            factors.add(i);
        }
    }

    // Check if k is less than the number of factors
    if (k > factors.size()) {
        return -1;
    }

    // Return the kth factor
