public int maxUniqueSplit(String s) {
    // Edge case: If the string is empty or has only one character, there is only one unique substring
    if (s.length() == 0 || s.length() == 1) {
        return 1;
    }

    // Initialize variables to keep track of the maximum number of unique substrings and the current number of unique substrings
    int maxUnique = 1;
    int currentUnique = 1;

    // Loop through each character in the string and check if it appears in the previous substrings
    for (int i = 1; i < s.length(); i++) {
        boolean found = false;
        for (int j = 0; j < i; j++) {
            if (s.charAt(i) == s.charAt(j)) {
                found = true;
                break;
            }
        }

        // If the character does not appear in any of the previous substrings, increment the number of unique substrings
        if (!found) {
            currentUnique++;
        }

        // If the number of unique substrings exceeds the maximum, update the maximum
        if (currentUnique > maxUnique) {
            maxUnique = currentUnique;
        }
    }

    return maxUnique;
}

public int maxUniqueSplit(String s) {
