    char[] arr = s.toCharArray();

    // Create a hash set to keep track of the unique characters
    Set<Character> set = new HashSet<>();

    // Initialize the maximum number of unique substrings to 0
    int maxUnique = 0;

    // Loop through the array of characters
    for (int i = 0; i < arr.length; i++) {
        char c = arr[i];

        // If the character is not in the set, add it and increment the maximum
        if (!set.contains(c)) {
            set.add(c);
            maxUnique++;
        }

        // If the character is already in the set, remove it and decrement the maximum
        else {
            set.remove(c);
            maxUnique--;
        }
    }

    // Return the maximum number of unique substrings
    return maxUnique;
}

