    for (int i = 0; i < A.length - 1; i++) {
        sums[i] = A[i] + A[i + 1];
    }

    // Check if each sum is a perfect square
    boolean[] isSquare = new boolean[A.length - 1];
    for (int i = 0; i < A.length - 1; i++) {
        isSquare[i] = (sums[i] % 2 == 0) && (Math.sqrt(sums[i]) == (int)Math.sqrt(sums[i]));
    }

    // Count the number of square permutations
    int count = 0;
    for (int i = 0; i < A.length; i++) {
        if (isSquare[i]) {
            count++;
        }
    }

    return count;
}

