        for (int j = i + 1; j < A.length; j++) {
            if (A[i] + A[j] == 2 * Math.pow(A[i + 1], 2)) {
                dp[i][j] = dp[i + 1][j] + dp[i + 1][j - 1];
            } else if (A[j] + A[i] == 2 * Math.pow(A[i + 1], 2)) {
