public static int findSmallestInteger(int n) {
    // Step 1: Extract the digits of the input integer
    int[] digits = new int[10];
    while (n > 0) {
        digits[n % 10]++;
        n /= 10;
    }

    // Step 2: Find the smallest rearrangement of the digits
    int smallest = -1;
    for (int i = 0; i < 10; i++) {
        for (int j = i + 1; j < 10; j++) {
            if (digits[i] > 0 && digits[j] > 0 && digits[i] < digits[j]) {
                int temp = digits[i];
                digits[i] = digits[j];
                digits[j] = temp;
                smallest = 0;
                for (int k = 0; k < 10; k++) {
                    smallest = smallest * 10 + digits[k];
                }
                break;
            }
        }
        if (smallest != -1) {
            break;
        }
    }

    // Step 3: Check if the rearrangement is greater than the original integer
    if (smallest > n) {
        return smallest;
    } else {
        return -1;
    }
}

public static int findSmallestInteger(int n) {
    int[] digits = new int[10];

    // Count the frequency of each digit in n
    for (int i = 0; i < 10; i++) {
        int digit = n % 10;
        digits[digit]++;
        n /= 10;
    }

    // Check if the digits can be rearranged to form a larger integer
    for (int i = 0; i < 10; i++) {
        for (int j = i + 1; j < 10; j++) {
            if (digits[i] > 0 && digits[j] > 0) {
                // Rearrange the digits
                digits[i]--;
                digits[j]--;

                // Check if the rearranged digits form a larger integer
                int rearranged = 0;
                for (int k = 0; k < 10; k++) {
                    rearranged = rearranged * 10 + digits[k];
                }

                if (rearranged > n) {
                    return rearranged;
                }
            }
        }
    }

    // If no larger integer can be formed, return -1
    return -1;
}

