    if (!isSortedByX(points)) {
        throw new IllegalArgumentException("Points must be sorted by x-coordinate in ascending order");
    }

    // Calculate the slope of the straight line passing through the three points
    double slope1 = (double) (points[1][1] - points[0][1]) / (points[1][0] - points[0][0]);
    double slope2 = (double) (points[2][1] - points[1][1]) / (points[2][0] - points[1][0]);

    // Check if the slopes are equal to 0, since a straight line has no slope
    if (slope1 == 0 || slope2 == 0) {
        return false;
    }

    // Check if the slopes are perpendicular to each other
    if (slope1 / slope2 == -1) {
        return true;
    }

    // Otherwise, the points do not form a boomerang
    return false;
