public static boolean isBoomerang(int[][] points) {
    // Check if the points form a closed loop
    if (!isClosedLoop(points)) {
        return false;
    }

    // Calculate the determinant of the matrix formed by the three points
    int determinant = determinant(points);

    // If the determinant is negative, the points form a boomerang
    return determinant < 0;
}

private static boolean isClosedLoop(int[][] points) {
    // Check if the first and last points are equal
    return points[0][0] == points[points.length - 1][0] && points[0][1] == points[points.length - 1][1];
}

private static int determinant(int[][] matrix) {
    // Calculate the determinant of the matrix
    int determinant = 0;
    for (int i = 0; i < matrix.length; i++) {
        determinant += matrix[i][0] * matrix[i][1];
    }
    return determinant;
}

public static int findNthUglyNumber(int n) {
    int[] factors = new int[] {2, 3, 5};
    int[] uglyNumbers = new int[n];
    uglyNumbers[0] = 1;
    int uglyNumberIndex = 0;
    for (int i = 1; i < n; i++) {
        int minFactor = findMinFactor(factors, uglyNumbers, uglyNumberIndex);
        if (minFactor == -1) {
            return -1;
        }
        uglyNumbers[i] = minFactor * factors[minFactor];
        factors[minFactor]++;
        uglyNumberIndex++;
    }
    return uglyNumbers[n-1];
}

private static int findMinFactor(int[] factors, int[] uglyNumbers, int startIndex) {
    int minFactor = -1;
    int minFactorValue = Integer.MAX_VALUE;
    for (int i = startIndex; i < factors.length; i++) {
        if (uglyNumbers[i] < minFactorValue) {
            minFactor = i;
            minFactorValue = uglyNumbers[i];
        }
    }
    return minFactor;
}

