    result.add(i);
  }
  result.sort((a, b) -> {
    String sa = String.valueOf(a);
    String sb = String.valueOf(b);
    for (int i = 0; i < Math.min(sa.length(), sb.length()); i++) {
      if (sa.charAt(i) != sb.charAt(i)) {
        return sa.charAt(i) - sb.charAt(i);
      }
    }
    return sa.length() - sb.length();
  });
  return result;
}

public static int calculateUniqueSum(int[] nums) {
   // sort the array to ensure that all duplicates are removed
   Arrays.sort(nums);
   // initialize the sum with the first element
   int sum = nums[0];
   // iterate over the rest of the array
   for (int i = 1; i < nums.length; i++) {
       // if the current element is not equal to the previous element
       if (nums[i] != nums[i - 1]) {
           // add the current element to the sum
           sum += nums[i];
       }
   }
   // return the sum
   return sum;
}

public static int calculateUniqueSum(int[] nums) {
    // Initialize an empty set to store unique elements
    Set<Integer> uniqueElements = new HashSet<>();

    // Add each element in the array to the set
    for (int num : nums) {
        uniqueElements.add(num);
    }

    // Calculate the sum of unique elements
    int sum = 0;
    for (int uniqueElement : uniqueElements) {
        sum += uniqueElement;
    }

    return sum;
}

