public static int minPerfectSquareSum(int n) {
        // Initialize a hash map to store the count of perfect square numbers
        Map<Integer, Integer> count = new HashMap<>();

        // Initialize a variable to store the minimum number of perfect square numbers
        int min = n;

        // Iterate from 1 to n
        for (int i = 1; i <= n; i++) {
            // If the square of the current number is less than or equal to n,
            // increment the count of perfect square numbers
            if (i * i <= n) {
                count.put(i * i, count.getOrDefault(i * i, 0) + 1);
            }
        }

        // Iterate from 1 to n
        for (int i = 1; i <= n; i++) {
            // If the square of the current number is greater than n,
            // break the loop since the minimum number of perfect square numbers
            // is at most the number of perfect square numbers found so far
            if (i * i > n) {
                break;
            }

            // If the count of perfect square numbers is greater than 1,
            // decrement the minimum number of perfect square numbers
            if (count.get(i * i) > 1) {
                min--;
            }
        }

        // Return the minimum number of perfect square numbers
        return min;
    }

