public static String reverseWords(String s) {
    // Split the input string into an array of words using " " as the delimiter
    String[] words = s.split(" ");

    // Initialize an empty string builder to store the reversed words
    StringBuilder reversedWords = new StringBuilder();

    // Iterate over each word in the array and reverse the characters
    for (String word : words) {
        // Reverse the word using the StringBuilder API
        StringBuilder reversedWord = new StringBuilder(word).reverse();

        // Add the reversed word to the string builder
        reversedWords.append(reversedWord).append(" ");
    }

    // Return the reversed words as a string
    return reversedWords.toString().trim();
}

public static String reverseWords(String s) {
    // Split the input string into an array of words using whitespace as the delimiter
    String[] words = s.split(" ");

    // Initialize an empty string to store the reversed words
    String reversedWords = "";

    // Iterate over the words array and reverse each word
    for (String word : words) {
        // Reverse the current word
        String reversedWord = new StringBuilder(word).reverse().toString();

        // Add the reversed word to the reversed words string
        reversedWords += reversedWord + " ";
    }

    // Return the reversed words string
    return reversedWords.trim();
}

public static String reverseWords(String s) {
    String[] words = s.split(" ");
    String result = "";
    for (int i = 0; i < words.length; i++) {
        String word = words[i];
        StringBuilder reversedWord = new StringBuilder();
        for (int j = word.length() - 1; j >= 0; j--) {
            reversedWord.append(word.charAt(j));
        }
        result += reversedWord.toString() + " ";
    }
    return result.trim();
}

