    String[] words = s.split(" ");
    String result = "";

    for (int i = 0; i < words.length; i++) {
        String word = words[i];
        char[] charArray = word.toCharArray();
        ArrayUtils.reverse(charArray);
        words[i] = new String(charArray);
    }

    for (int i = 0; i < words.length; i++) {
        result += words[i] + " ";
    }

    return result.trim();
}
